-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261030060000' and name='tg_room_pin')=1 then '예' else '아니오' end as value
union all select 'pin column nullable timestamptz',case when exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_feed_rooms') and attname='pinned_at' and not attisdropped and atttypid='timestamptz'::regtype and not attnotnull) then '예' else '아니오' end
union all select 'pin function: definer, empty search_path, no anon or PUBLIC execute',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_feed_room_pin(text,boolean)') and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'pin function: authenticated only',case when has_function_privilege('authenticated','public.app_feed_room_pin(text,boolean)','execute') and not has_function_privilege('service_role','public.app_feed_room_pin(text,boolean)','execute') then '예' else '아니오' end
union all select 'rooms: no write privilege for anon or authenticated',case when not has_any_column_privilege('anon','public.app_feed_rooms','select,insert,update,references') and not has_any_column_privilege('authenticated','public.app_feed_rooms','insert,update,references') then '예' else '아니오' end
union all select 'rooms guard trigger and restrictive policy present',case when (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_rooms') and tgname='trg_op_feature_guard' and not tgisinternal and tgenabled<>'D')=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_feed_rooms') and polname='op_feature_read' and not polpermissive)=1 then '예' else '아니오' end
union all select 'rooms rows',(select count(*)::text from public.app_feed_rooms)
union all select 'rooms grants policies triggers hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_feed_rooms')),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_feed_rooms')),'')
  ||coalesce((select string_agg(t.tgname::text||':'||t.tgenabled::text||':'||t.tgfoid::regproc::text,',' order by t.tgname) from pg_trigger t where t.tgrelid=to_regclass('public.app_feed_rooms') and not t.tgisinternal),''));
